export function toNativeDigits(val: string | number | undefined | null, explicitLang?: LangMode): string {
  if (val === undefined || val === null) return ''
  const str = String(val)
  const lang = explicitLang || useStore.getState().lang || 'en'
  const digits = NATIVE_DIGITS[lang]
  if (!digits || lang === 'en') return str
  return str.replace(/[0-9]/g, (d) => digits[Number(d)] ?? d)
}

