export function translateSector(sectorName: string | undefined | null, lang: LangMode): string {
  if (!sectorName) return ''
  const trimmed = sectorName.trim()
  const found = SECTOR_NAMES[trimmed]
  if (found && found[lang]) {
    return found[lang]!
  }
  const lower = trimmed.toLowerCase()
  for (const [k, v] of Object.entries(SECTOR_NAMES)) {
    if (k.toLowerCase() === lower && v[lang]) {
      return v[lang]!
    }
  }
  return trimmed
}

