export function t(key: string, vars?: Record<string, string | number>, explicitLang?: LangMode): string {
  const lang = explicitLang || useStore.getState().lang || 'en'
  let text = dictionary[key]?.[lang] || dictionary[key]?.['en'] || key

  if (vars) {
    Object.entries(vars).forEach(([k, v]) => {
      const localizedVal = toNativeDigits(v, lang)
      text = text.replace(new RegExp(`\\{${k}\\}`, 'g'), localizedVal)
    })
  }

  return text
}

export function useTranslation() {
  const lang = useStore((state) => state.lang)
  const setLang = useStore((state) => state.setLang)

  const translate = React.useCallback(
    (key: string, vars?: Record<string, string | number>) => {
      return t(key, vars, lang)
    },
    [lang]
  )

  const formatNum = React.useCallback(
    (val: string | number | undefined | null) => {
      return toNativeDigits(val, lang)
    },
    [lang]
  )

  return React.useMemo(
    () => ({ t: translate, lang, setLang, formatNum, toNativeDigits: formatNum }),
    [translate, lang, setLang, formatNum]
  )
}

export function triggerPageTranslation(langCode: string) {
  if (typeof window === 'undefined') return

  try {
    const cookieVal = langCode === 'en' ? '' : `/en/${langCode}`
    const expires = langCode === 'en' ? 'Thu, 01 Jan 1970 00:00:00 UTC' : 'Fri, 31 Dec 9999 23:59:59 GMT'
    document.cookie = `googtrans=${cookieVal}; expires=${expires}; path=/;`
    if (window.location.hostname && window.location.hostname !== 'localhost') {
      document.cookie = `googtrans=${cookieVal}; expires=${expires}; path=/; domain=.${window.location.hostname};`
      document.cookie = `googtrans=${cookieVal}; expires=${expires}; path=/; domain=${window.location.hostname};`
    }

    const combo = document.querySelector('.goog-te-combo') as HTMLSelectElement | null
    if (combo) {
      combo.value = langCode === 'en' ? '' : langCode
      combo.dispatchEvent(new Event('change'))
    }
  } catch (err) {
    console.warn('Page translation trigger error:', err)
  }
}

